/**
 * Jack-in-the-Box category bank — original content.
 *
 * Each category lists accepted answers in three tiers (common → rare). Bots only "know" the tiers
 * that suit their difficulty, so they freeze up as the obvious answers run out.
 *
 * Format: comma-separated answers; `|` separates spelling variants/aliases of the SAME answer
 * (the first is the canonical display form). Matching ignores case, accents, punctuation,
 * leading "a/an/the" and simple plurals, and forgives small typos — so lists hold singulars only.
 *
 * Rejecting a genuinely valid answer is the most frustrating failure for this game: lists are
 * deliberately generous. When adding categories, prefer ones with a well-defined, enumerable set.
 */
export interface Category {
  id: string;
  /** Shown as "Name a …" — keep it short. */
  prompt: string;
  tiers: [common: string, uncommon: string, rare: string];
}

